(function () {
  var here = location.pathname.replace(/\/+$/, '') || '/';
  document.querySelectorAll('[data-bz-section="site-header"] [data-bz-node="main-nav"] a[href]').forEach(function (a) {
    var path = (a.getAttribute('href') || '').split(/[?#]/)[0].replace(/\/+$/, '') || '/';
    if (path === here && !a.hasAttribute('aria-current')) a.setAttribute('aria-current', 'page');
  });
})();
